#include "PluginEditor.h"
MageAudioProcessorEditor::MageAudioProcessorEditor(MageAudioProcessor& x):AudioProcessorEditor(x),p(x){setSize(1000,680);title.setText("ᛗ  M A G E  ᛗ",juce::dontSendNotification);title.setFont(juce::Font(32,juce::Font::bold));title.setColour(juce::Label::textColourId,juce::Colour(0xffdf77ff));title.setJustificationType(juce::Justification::centred);addAndMakeVisible(title);const char* ids[]={"gain","bass","mid","treble","presence","depth","master"};const char* names[]={"GAIN","BASS","MID","TREBLE","PRESENCE","DEPTH","MASTER"};for(int i=0;i<7;i++){knobs[i].setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);knobs[i].setTextBoxStyle(juce::Slider::TextBoxBelow,false,60,20);knobs[i].setColour(juce::Slider::rotarySliderFillColourId,juce::Colour(0xff45c8ff));knobs[i].setColour(juce::Slider::thumbColourId,juce::Colour(0xffff65d5));addAndMakeVisible(knobs[i]);labels[i].setText(names[i],juce::dontSendNotification);labels[i].setColour(juce::Label::textColourId,juce::Colours::white);labels[i].setJustificationType(juce::Justification::centred);addAndMakeVisible(labels[i]);attachments[i]=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,ids[i],knobs[i]);}}
void MageAudioProcessorEditor::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff080b14));g.setGradientFill(juce::ColourGradient(juce::Colour(0xff14304c),0,0,juce::Colour(0xff30132d),getWidth(),getHeight(),false));g.fillRoundedRectangle(getLocalBounds().toFloat().reduced(10),18);g.setColour(juce::Colour(0xff45c8ff));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(10),18,2);g.setColour(juce::Colour(0xffff65d5));g.drawLine(40,90,getWidth()-40,90,2);}
void MageAudioProcessorEditor::resized(){title.setBounds(0,20,getWidth(),60);int w=getWidth()/7;for(int i=0;i<7;i++){labels[i].setBounds(i*w,120,w,30);knobs[i].setBounds(i*w+8,150,w-16,150);}}
